function normalizeReviewer(value){return {name:String(value?.name||'').trim().slice(0,60),avatar:safeImage(value?.avatar||'')}}
function reviewerFor(f){return normalizeReviewer(reviewerProfile.configured?reviewerProfile:f?.reviewer||reviewerProfile)}
function reviewerAvatar(person,cls=''){const name=person.name||'Nhân vật của bạn',initials=person.name?person.name.trim().split(/\s+/).slice(0,2).map(s=>s[0]).join('').toLocaleUpperCase():'A';return person.avatar?`<img class="reviewer-avatar ${cls}" src="${esc(assetUrl(person.avatar))}" alt="Avatar ${esc(name)}">`:`<span class="reviewer-avatar reviewer-initials ${cls}" aria-label="Avatar ${esc(name)}">${esc(initials)}</span>`}
function reviewComment(f,preview=true){if(!f.review?.trim())return '';const person=reviewerFor(f),long=f.review.length>320||f.review.split('\n').length>5;return `<section class="review-comment" aria-label="Comment về phim"><div class="reviewer-heading">${reviewerAvatar(person)}<div class="reviewer-name"><strong>Reviewed By</strong><span>${esc(person.name||'Nhân vật của bạn')}</span></div>${preview&&long&&!f.spoilers?'<button class="text-button review-expand" id="fullReviewBtn">Đọc đầy đủ ↗</button>':''}</div>${f.spoilers&&preview?'<div class="compact-spoiler"><span>Comment này có spoiler.</span><button class="text-button" id="revealBtn">Hiện comment ↗</button></div>':`<blockquote class="review-comment-text ${preview?'review-preview':''}">“${esc(f.review)}”</blockquote>`}</section>`}
