let token='',connected=false,remoteShas=new Map(),assetCache=new Map(),editingId=null,activeId=null,search='',genre='',sort='watched',unratedOnly=false,extraWatches=[],busy=false;
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function assetUrl(src){return typeof src==='string'&&src.startsWith('/assets/')?'./'+src.slice(1):src}
function safeImage(s){return typeof s==='string'&&(/^(https?:\/\/|data:image\/(png|jpeg|webp);base64,|\/assets\/|assets\/posters\/)/i.test(s))?s:''}
function today(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s||'')&&!Number.isNaN(Date.parse(s))}
function normalize(f){if(!f||typeof f!=='object'||typeof f.title!=='string'||!f.title.trim())throw Error('File thiếu tên phim.');let id=String(f.id||crypto.randomUUID());if(!/^[a-zA-Z0-9_-]{1,100}$/.test(id))throw Error('ID phim không hợp lệ.');const ratings={};for(const[k]of criteria){const v=f.ratings?.[k];ratings[k]=v===null||v===undefined||v===''?null:Number(v);if(ratings[k]!==null&&(!Number.isFinite(ratings[k])||ratings[k]<0||ratings[k]>5||ratings[k]*2%1))throw Error('Điểm không hợp lệ.')}return {id,title:f.title.slice(0,180),originalTitle:String(f.originalTitle||''),year:Number(f.year)||null,genres:Array.isArray(f.genres)?canonicalGenres(f.genres):[],country:String(f.country||''),runtime:Number(f.runtime)||null,poster:safeImage(f.poster),director:String(f.director||''),screenplay:String(f.screenplay||''),cinematography:String(f.cinematography||''),music:String(f.music||''),cast:Array.isArray(f.cast)?f.cast.map(String):[],ratings,watches:Array.isArray(f.watches)?f.watches.filter(w=>w&&typeof w==='object').map(w=>({date:validDate(w.date)?w.date:'',venue:String(w.venue||'')})):[],review:String(f.review||''),reviewer:normalizeReviewer(f.reviewer),spoilers:!!f.spoilers,favorite:!!f.favorite,demo:!!f.demo,updatedAt:String(f.updatedAt||'')}}
function score(f){const v=criteria.map(([k])=>f.ratings[k]);return v.some(x=>x===null||x===undefined)?null:v.reduce((a,b)=>a+b,0)/4}
function scoreText(f){const n=score(f);return n===null?'—':Number(n.toFixed(1)).toString()}
function badge(f){return RATING_LABELS[ratingLevel(score(f))]||'Chưa chấm đủ'}
