 if($('#panelEdit'))$('#panelEdit').onclick=()=>{$('#filmPanel').close();openEditor(f);if(section==='review')setEditorStep('review')};
 if($('#panelAddWatch'))$('#panelAddWatch').onclick=()=>{$('#filmPanel').close();openEditor(f);addWatch()};
 if($('#panelDelete'))$('#panelDelete').onclick=async()=>{await deleteFilm(f);if(!films.some(x=>x.id===f.id))$('#filmPanel').close()};
