async function deleteFilm(f){if(!requireOwner())return;if(!confirm(`Xóa “${f.title}” khỏi bộ sưu tập?${connected?' Nếu có trên GitHub, file đó cũng sẽ được xóa.':''}`))return;try{if(connected){const path=`${prefs.folder}/${f.id}.md`;let remote;try{remote=await gh('contents/'+encodePath(path))}catch(e){if(e.status!==404)throw e}if(remote){if(remoteShas.has(f.id)&&remoteShas.get(f.id)!==remote.sha)throw Error('Phim đã đổi trên GitHub. Kết nối lại để đọc bản mới trước khi xóa.');await gh('contents/'+encodePath(path),{method:'DELETE',body:JSON.stringify({message:'Delete film: '+f.title,sha:remote.sha,branch:prefs.branch})})}}if(persist(films.filter(x=>x.id!==f.id))){location.hash='';route();toast('Đã xóa phim.')}}catch(err){toast(err.message)}}
function toMd(f,poster=f.poster){const keys=['id','title','originalTitle','year','genres','country','runtime','director','screenplay','cinematography','music','cast','ratings','watches','reviewer','spoilers','favorite','demo','updatedAt'];let lines=['---','schemaVersion: 1'];for(const k of keys)lines.push(k+': '+JSON.stringify(k==='reviewer'?reviewerFor(f):f[k]??null));lines.push('poster: '+JSON.stringify(poster),'---','',f.review||'','');return lines.join('\n')}
function parseMd(s){const m=s.replace(/^\uFEFF/,'').match(/^---\r?\n([\s\S]*?)\r?\n---(?:\r?\n|$)([\s\S]*)$/);if(!m)throw Error('Markdown cần có frontmatter giữa hai dòng --- .');let data={};for(const l of m[1].split(/\r?\n/)){const match=l.match(/^([a-zA-Z][\w]*):\s*(.*)$/);if(!match||['__proto__','constructor','prototype'].includes(match[1]))continue;try{data[match[1]]=JSON.parse(match[2])}catch{data[match[1]]=match[2].replace(/^['"]|['"]$/g,'')}}data.review=m[2].trim();return normalize(data)}
const encoder=new TextEncoder();function bytes(s){return encoder.encode(s)}function b64(b){let s='';for(let i=0;i<b.length;i+=8192)s+=String.fromCharCode(...b.subarray(i,i+8192));return btoa(s)}function unb64(s){return Uint8Array.from(atob(s.replace(/\s/g,'')),c=>c.charCodeAt(0))}
const crcTable=Array.from({length:256},(_,n)=>{for(let i=0;i<8;i++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});function crc(b){let n=0xffffffff;for(const c of b)n=crcTable[(n^c)&255]^(n>>>8);return(n^0xffffffff)>>>0}
function zip(entries){let parts=[],central=[],offset=0;for(const[name,data]of entries){const n=bytes(name),c=crc(data),h=new Uint8Array(30),v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint32(14,c,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,n.length,true);parts.push(h,n,data);const ch=new Uint8Array(46),cv=new DataView(ch.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,c,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,n.length,true);cv.setUint32(42,offset,true);central.push(ch,n);offset+=30+n.length+data.length}const size=central.reduce((s,b)=>s+b.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,entries.length,true);ev.setUint16(10,entries.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'})}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function posterData(f){const src=assetCache.get(f.poster)||safeImage(f.poster);if(!src)return null;if(src.startsWith('data:')){const m=src.match(/^data:image\/(\w+);base64,(.*)$/);return m?{data:unb64(m[2]),ext:m[1]==='jpeg'?'jpg':m[1]}:null}if(/^\/?assets\//.test(src)){const r=await fetch(assetUrl(src));if(!r.ok)throw Error('Không đọc được poster mẫu.');return {data:new Uint8Array(await r.arrayBuffer()),ext:src.toLowerCase().endsWith('.png')?'png':/\.jpe?g$/i.test(src)?'jpg':'webp'}}return null}
async function exportZip(list=films){try{const entries=[];for(const f of list){const p=await posterData(f);let poster=f.poster;if(p){poster=`assets/posters/${f.id}.${p.ext}`;entries.push([poster,p.data])}entries.push([`content/films/${f.id}.md`,bytes(toMd(f,poster))])}entries.push(['README.md',bytes('# Paul\'s Movie Log\n\nEach film is a UTF-8 Markdown file. YAML frontmatter uses JSON-compatible values; the body is your review. Ratings: integers 1–5 (legacy fractional values remain readable); overall = mean of all four, rounded only for display. Null means unrated. Watches may have an empty date. Dates use YYYY-MM-DD. Film IDs are stable.\n\nImport the .md files through Data & connections. Import the assets/posters folder to restore local poster images. Remote poster URLs remain remote; uploaded and demo posters are included. Reviewer name and avatar are included in each movie Markdown record. GitHub repository and credentials are not included.\n\nDemo records are illustrative, not verified movie metadata.\n')]);download(zip(entries),'pauls-movie-log-'+today()+'.zip');toast('Đã xuất Markdown và poster.')}catch(e){toast('Xuất thất bại: '+e.message)}}
async function importMarkdown(files){if(!requireOwner())return;try{const parsed=[];for(const file of files){if(file.size>4*1024*1024)throw Error(file.name+' vượt quá 4 MB.');parsed.push(parseMd(await file.text()))}const existing=parsed.filter(f=>films.some(x=>x.id===f.id)).length;if(existing&&!confirm(`Có ${existing} phim trùng ID. Thay bằng bản nhập vào?`))return;const map=new Map(films.map(f=>[f.id,f]));parsed.forEach(f=>map.set(f.id,f));if(persist([...map.values()])){route();toast(`Đã nhập ${parsed.length} phim.`)}}catch(e){toast('Không nhập được: '+e.message)}}
