function encodePath(p){return p.split('/').map(encodeURIComponent).join('/')}
async function gh(path,opts={}){if((opts.method||'GET').toUpperCase()!=='GET'&&!ownerAuthorized)throw Error('Chưa xác thực chủ sở hữu.');const url=`https://api.github.com/repos/${prefs.repo}/${path}${path.includes('?')?'&':'?'}ref=${encodeURIComponent(prefs.branch)}`;const r=await fetch(url,{...opts,headers:{Accept:'application/vnd.github+json',Authorization:'Bearer '+token,'X-GitHub-Api-Version':'2022-11-28',...(opts.body?{'Content-Type':'application/json'}:{})}});if(!r.ok){let message;try{message=(await r.json()).message}catch{}const e=Error(`GitHub ${r.status}: ${message||r.statusText}`);e.status=r.status;throw e}return r.status===204?null:r.json()}
function validatePrefs(p){if(!/^[a-zA-Z0-9_.-]+\/[a-zA-Z0-9_.-]+$/.test(p.repo))throw Error('Repository có dạng username/repository.');if(!p.branch.trim()||!p.folder||p.folder.startsWith('/')||p.folder.split('/').some(s=>s==='..'||!s)||!/^[a-zA-Z0-9_./-]+$/.test(p.folder))throw Error('Branch hoặc thư mục không hợp lệ.')}
