async function putFile(path,data,message,expected){let current;try{current=await gh('contents/'+encodePath(path))}catch(e){if(e.status!==404)throw e}if(expected!==undefined&&(current?.sha||null)!==expected)throw Error('File đã thay đổi trên GitHub: '+path+'. Kết nối lại để đọc bản mới.');return gh('contents/'+encodePath(path),{method:'PUT',body:JSON.stringify({message,content:b64(data),branch:prefs.branch,...(current?{sha:current.sha}:{})})})}
async function syncAll(){if(!requireOwner())return;if(!connected||!token){toast('Kết nối GitHub trước khi đồng bộ.');return}if(busy)return;busy=true;$('#syncAllBtn').disabled=true;const snapshot=structuredClone(films);try{githubStatus('Đang kiểm tra dữ liệu GitHub…');const ref=await gh('git/ref/heads/'+encodePath(prefs.branch)),head=ref.object.sha,commit=await gh('git/commits/'+head),entries=[],savedIds=[];let done=0;for(const f of snapshot){githubStatus(`Đang chuẩn bị ${++done}/${snapshot.length}: ${f.title}`);const mdPath=`${prefs.folder}/${f.id}.md`,expected=remoteShas.get(f.id)||null;let remote;try{remote=await gh('contents/'+encodePath(mdPath))}catch(e){if(e.status!==404)throw e}if((remote?.sha||null)!==expected)throw Error('Phim đã thay đổi trên GitHub: '+f.title+'. Kết nối lại để đọc trước khi ghi.');let poster=f.poster;const p=await posterData(f);if(p){poster=`assets/posters/${f.id}.${p.ext}`;const blob=await gh('git/blobs',{method:'POST',body:JSON.stringify({content:b64(p.data),encoding:'base64'})});entries.push({path:poster,mode:'100644',type:'blob',sha:blob.sha})}const content=toMd(f,poster),current=remote?.content?new TextDecoder().decode(unb64(remote.content)):null;if(content!==current){const blob=await gh('git/blobs',{method:'POST',body:JSON.stringify({content,encoding:'utf-8'})});entries.push({path:mdPath,mode:'100644',type:'blob',sha:blob.sha});savedIds.push([f.id,blob.sha])}}if(!entries.length){githubStatus('Dữ liệu đã đồng bộ, không có thay đổi.');return}const tree=await gh('git/trees',{method:'POST',body:JSON.stringify({base_tree:commit.tree.sha,tree:entries})});if(tree.sha===commit.tree.sha){githubStatus('Dữ liệu đã đồng bộ, không có thay đổi.');return}const saved=await gh('git/commits',{method:'POST',body:JSON.stringify({message:`Update movie log (${snapshot.length} films)`,tree:tree.sha,parents:[head]})});await gh('git/refs/heads/'+encodePath(prefs.branch),{method:'PATCH',body:JSON.stringify({sha:saved.sha,force:false})});for(const[id,sha]of savedIds)remoteShas.set(id,sha);githubStatus(`Đã lưu ${snapshot.length} phim trong một lần cập nhật GitHub. Web sẽ tự publish lại.`);toast('Đã đồng bộ lên GitHub.')}catch(e){githubStatus('Chưa hoàn tất đồng bộ. '+e.message,true)}finally{busy=false;$('#syncAllBtn').disabled=false}}
